    except:
        print(f"- {layer}: Not available")

# Check if there's any building-related data
print("\nChecking for building footprint data...")
building_layers = []
for layer in layers:
    try:
        layer_obj = load(layer)
        desc = describe(layer_obj)
        if "polygon" in desc.lower() or "point" in desc.lower():
            if "building" in desc.lower() or "structure" in desc.lower():
                building_layers.append(layer)
    except:
        continue

if not building_layers:
    print("No building footprint data found in the available layers.")
else:
    print("Building-related layers found:", building_layers)
